CREATE VIEW mart_play_next_v2 AS SELECT c.GameKey, c.GameID, c.GameTitle, c.PlayStatusName, c.final_recommendation_score, c.playability_status, c.recommendation_status, c.recommendation_context FROM mart_recommendation_context_v1 AS c WHERE ((c.recommendation_context = 'Playable Backlog') AND (c.final_recommendation_score IS NOT NULL) AND (NOT (c.GameID = ANY(SELECT GameID FROM PreferenceSeedGame)))) ORDER BY c.final_recommendation_score DESC;
